package aws

import (
	"encoding/json"
	"fmt"
	"reflect"
)

// Resource is any strongly typed AWS CloudFormation resource, as generated by
// goformation (e.g. *s3.Bucket, *iam.Role, *ec2.Instance). Every goformation
// resource satisfies this interface via its AWSCloudFormationType method, so a
// challenge author never implements it by hand:
//
//	import "github.com/awslabs/goformation/v7/cloudformation/s3"
//
//	var _ aws.Resource = &s3.Bucket{}
//
// The Cloud Control API that the host drives behind pkg/challenge speaks the
// exact same resource-type names ("AWS::S3::Bucket") and property shapes that
// these structs encode, which is why they can be handed straight to
// Context.Create / Read / Update / Delete.
type Resource interface {
	// AWSCloudFormationType returns the Cloud Control type name, e.g.
	// "AWS::S3::Bucket". goformation implements this on the pointer receiver,
	// so authors always pass a pointer (&s3.Bucket{...}).
	AWSCloudFormationType() string
}

// desiredState renders a resource into the (typeName, desiredStateJSON) pair
// expected by the Cloud Control CreateResource call.
//
// goformation's own MarshalJSON wraps a resource as a CloudFormation template
// fragment: {"Type": "...", "Properties": {...}}. Cloud Control's DesiredState
// wants only the Properties object, so we marshal through goformation and then
// lift the Properties sub-document back out. This keeps us compatible with
// every goformation resource without re-encoding their JSON tags by hand.
func desiredState(r Resource) (typeName string, desired string, err error) {
	raw, err := json.Marshal(r)
	if err != nil {
		return "", "", fmt.Errorf("marshal resource: %w", err)
	}
	var wrapper struct {
		Type       string          `json:"Type"`
		Properties json.RawMessage `json:"Properties"`
	}
	if err := json.Unmarshal(raw, &wrapper); err != nil {
		return "", "", fmt.Errorf("extract properties: %w", err)
	}
	if wrapper.Type == "" {
		wrapper.Type = r.AWSCloudFormationType()
	}
	if len(wrapper.Properties) == 0 {
		wrapper.Properties = json.RawMessage("{}")
	}
	return wrapper.Type, string(wrapper.Properties), nil
}

// decodeProperties fills a goformation resource from a Cloud Control resource
// state document (the raw properties JSON returned by ReadResource).
//
// goformation resources ship a custom UnmarshalJSON that (a) expects the
// {"Type","Properties"} template wrapper and (b) rejects unknown fields. Cloud
// Control instead returns the bare properties object, frequently including
// read-only attributes (Arn, DomainName, ...) that the writable struct does not
// model. Both traits make the stock unmarshaler unusable here.
//
// Only the top-level resource types carry that custom unmarshaler; the nested
// property structs decode with the default rules. So we rebuild an identical,
// method-less twin struct via reflection, decode into it with the tolerant
// default decoder (unknown fields ignored), and copy the fields back. The twin
// has byte-identical field types, so every value assigns cleanly.
func decodeProperties(into Resource, data []byte) (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("decode %s state: %v", into.AWSCloudFormationType(), r)
		}
	}()

	v := reflect.ValueOf(into)
	if v.Kind() != reflect.Pointer || v.IsNil() {
		return fmt.Errorf("decode state: destination must be a non-nil pointer, got %T", into)
	}
	v = v.Elem()
	if v.Kind() != reflect.Struct {
		return fmt.Errorf("decode state: destination must point at a struct, got %T", into)
	}

	t := v.Type()
	fields := make([]reflect.StructField, 0, t.NumField())
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		if f.PkgPath != "" {
			// Unexported field: reflect.StructOf cannot reproduce it and json
			// never touches it anyway, so drop it from the twin.
			continue
		}
		fields = append(fields, f)
	}

	twin := reflect.New(reflect.StructOf(fields))
	if err := json.Unmarshal(data, twin.Interface()); err != nil {
		return fmt.Errorf("decode %s state: %w", into.AWSCloudFormationType(), err)
	}

	twinElem := twin.Elem()
	for _, f := range fields {
		src := twinElem.FieldByName(f.Name)
		dst := v.FieldByName(f.Name)
		if dst.CanSet() {
			dst.Set(src)
		}
	}
	return nil
}
